INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0263-a03-110-216', 'p0263', 'houhanshu', 'a03-110', '《二十四史-後漢書-志第二十‧郡國二》', '繁陽　內黃左傳襄十九年會于柯，杜預曰縣東北有柯城。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0263-a03-110-217', 'p0263', 'houhanshu', 'a03-110', '《二十四史-後漢書-志第二十‧郡國二》', '昭九年荀盈卒于戲陽，杜預曰縣北有戲陽城。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0263-a03-110-218', 'p0263', 'houhanshu', 'a03-110', '《二十四史-後漢書-志第二十‧郡國二》', '魏　元城左傳成七年會馬陵，杜預曰縣東南有地名馬陵。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0263-a03-110-219', 'p0263', 'houhanshu', 'a03-110', '《二十四史-後漢書-志第二十‧郡國二》', '左傳定七年盟于沙亭，杜預曰在縣東南。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0263-a03-110-220', 'p0263', 'houhanshu', 'a03-110', '《二十四史-後漢書-志第二十‧郡國二》', '黎陽左傳定十四年會于牽，杜預曰縣東北有牽城。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0263-a03-110-221', 'p0263', 'houhanshu', 'a03-110', '《二十四史-後漢書-志第二十‧郡國二》', '左傳襄三年諸侯會雞澤，杜預曰在縣西南。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0263-a03-110-222', 'p0263', 'houhanshu', 'a03-110', '《二十四史-後漢書-志第二十‧郡國二》', '杜預曰縣西南有肥累城。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0263-a03-110-223', 'p0263', 'houhanshu', 'a03-110', '《二十四史-後漢書-志第二十‧郡國二》', '左傳昭十二年晉荀吳入昔陽，杜預曰沾縣東有昔陽城。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0263-a03-110-224', 'p0263', 'houhanshu', 'a03-110', '《二十四史-後漢書-志第二十‧郡國二》', '望都左傳晉伐鮮虞及中人，杜預曰縣西北有中人城。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0263-a03-111-225', 'p0263', 'houhanshu', 'a03-111', '《二十四史-後漢書-志第二十一‧郡國三》', '左傳成十六年衞伐鄭鳴鴈，杜預曰在雍丘縣西北。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0263-a03-111-226', 'p0263', 'houhanshu', 'a03-111', '《二十四史-後漢書-志第二十一‧郡國三》', '左傳莊三年次于滑，杜預曰在縣西北。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0263-a03-111-227', 'p0263', 'houhanshu', 'a03-111', '《二十四史-後漢書-志第二十一‧郡國三》', '襄元年會鄫，杜預曰縣東南有鄫城。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0263-a03-111-228', 'p0263', 'houhanshu', 'a03-111', '《二十四史-後漢書-志第二十一‧郡國三》', '外黃左傳「惠公季年，敗宋師于黃」，杜預曰宋邑，縣東有黃城。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0263-a03-111-229', 'p0263', 'houhanshu', 'a03-111', '《二十四史-後漢書-志第二十一‧郡國三》', '左傳桓十二年「盟于武父」，杜預曰縣東北有武父城。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0263-a03-111-230', 'p0263', 'houhanshu', 'a03-111', '《二十四史-後漢書-志第二十一‧郡國三》', '」左傳哀十三年盟黃池，杜預曰在封邱縣南。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0263-a03-111-231', 'p0263', 'houhanshu', 'a03-111', '《二十四史-後漢書-志第二十一‧郡國三》', '」　酸棗左傳鄭太叔至于廩延，杜預曰縣北有延津。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0263-a03-111-232', 'p0263', 'houhanshu', 'a03-111', '《二十四史-後漢書-志第二十一‧郡國三》', '襄五年會城棣，杜預曰縣西南有棣城。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0263-a03-111-233', 'p0263', 'houhanshu', 'a03-111', '《二十四史-後漢書-志第二十一‧郡國三》', '左傳僖十五年會牡丘，次于匡，杜預曰匡在縣西南。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0263-a03-111-234', 'p0263', 'houhanshu', 'a03-111', '《二十四史-後漢書-志第二十一‧郡國三》', '昭十三年會平丘，杜預曰縣西南有平丘城。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0263-a03-111-235', 'p0263', 'houhanshu', 'a03-111', '《二十四史-後漢書-志第二十一‧郡國三》', '左傳成九年會于蒲，杜預曰在縣西南。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0263-a03-111-236', 'p0263', 'houhanshu', 'a03-111', '《二十四史-後漢書-志第二十一‧郡國三》', '左傳僖二十八年衞人盟宛濮，杜預曰近濮水。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0263-a03-111-237', 'p0263', 'houhanshu', 'a03-111', '《二十四史-後漢書-志第二十一‧郡國三》', '左傳宣二年鄭破宋師大棘，杜預曰在襄邑縣南。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0263-a03-111-238', 'p0263', 'houhanshu', 'a03-111', '《二十四史-後漢書-志第二十一‧郡國三》', '左傳僖五年齊侯會于首止，杜預曰在襄邑東南，有首鄉。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0263-a03-111-239', 'p0263', 'houhanshu', 'a03-111', '《二十四史-後漢書-志第二十一‧郡國三》', '」杜預曰：「戴在外黃東南。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0263-a03-111-240', 'p0263', 'houhanshu', 'a03-111', '《二十四史-後漢書-志第二十一‧郡國三》', '濮陽，古昆吾國，杜預曰古衞也。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0263-a03-111-241', 'p0263', 'houhanshu', 'a03-111', '《二十四史-後漢書-志第二十一‧郡國三》', '」左傳曰「衞，顓頊之墟」，杜預曰帝丘，昆吾氏因之，故曰昆吾之墟，縣城內有顓頊冢。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0263-a03-111-242', 'p0263', 'houhanshu', 'a03-111', '《二十四史-後漢書-志第二十一‧郡國三》', '左傳曰宣十二年盟清丘，杜預曰縣東南。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0263-a03-111-243', 'p0263', 'houhanshu', 'a03-111', '《二十四史-後漢書-志第二十一‧郡國三》', '左傳曰定八年會于瓦，杜預曰縣東北。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0263-a03-111-244', 'p0263', 'houhanshu', 'a03-111', '《二十四史-後漢書-志第二十一‧郡國三》', '杜預曰：「縣東南有韋城。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0263-a03-111-245', 'p0263', 'houhanshu', 'a03-111', '《二十四史-後漢書-志第二十一‧郡國三》', '東阿左傳桓十年會于桃丘，杜預曰縣東南有桃城。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0263-a03-111-246', 'p0263', 'houhanshu', 'a03-111', '《二十四史-後漢書-志第二十一‧郡國三》', '襄十四年孫林父敗衞侯于阿澤，杜預曰縣西南大澤。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0263-a03-111-247', 'p0263', 'houhanshu', 'a03-111', '《二十四史-後漢書-志第二十一‧郡國三》', '杜預注傳曰衞作新臺在縣北。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0263-a03-111-248', 'p0263', 'houhanshu', 'a03-111', '《二十四史-後漢書-志第二十一‧郡國三》', '左傳文元年會于戚，鄭救晉中行氏，晉敗鄭鐵，杜預曰戚城南有鐵丘。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0263-a03-111-249', 'p0263', 'houhanshu', 'a03-111', '《二十四史-後漢書-志第二十一‧郡國三》', '左傳莊三十二年「城小穀」，杜預曰城中有管仲井。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0263-a03-111-250', 'p0263', 'houhanshu', 'a03-111', '《二十四史-後漢書-志第二十一‧郡國三》', '又傳曰埋長狄榮如首於周首之北門，杜預曰縣東北有周首亭。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0263-a03-111-251', 'p0263', 'houhanshu', 'a03-111', '《二十四史-後漢書-志第二十一‧郡國三》', '左傳僖二十六年追齊師至酅，杜預曰縣西有地名酅下。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0263-a03-111-252', 'p0263', 'houhanshu', 'a03-111', '《二十四史-後漢書-志第二十一‧郡國三》', '左傳昭二十五年臧會奔郈，杜預曰縣東南有郈鄉亭。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0263-a03-111-253', 'p0263', 'houhanshu', 'a03-111', '《二十四史-後漢書-志第二十一‧郡國三》', '左傳桓十一年會于闞，杜預曰在須昌縣東南。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0263-a03-111-254', 'p0263', 'houhanshu', 'a03-111', '《二十四史-後漢書-志第二十一‧郡國三》', '杜預曰：「須句，古國，在西北。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0263-a03-111-255', 'p0263', 'houhanshu', 'a03-111', '《二十四史-後漢書-志第二十一‧郡國三》', '左傳僖三年會陽穀，杜預曰在縣北。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0263-a03-111-256', 'p0263', 'houhanshu', 'a03-111', '《二十四史-後漢書-志第二十一‧郡國三》', '亢父左傳襄十三年「取邿」，杜預曰縣有邿亭。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0263-a03-111-257', 'p0263', 'houhanshu', 'a03-111', '《二十四史-後漢書-志第二十一‧郡國三》', '哀六年「城邾瑕」，杜預曰縣北有邾瑕城。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0263-a03-111-258', 'p0263', 'houhanshu', 'a03-111', '《二十四史-後漢書-志第二十一‧郡國三》', '紅亭在縣西北，杜預曰接宋、衞也。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0263-a03-111-259', 'p0263', 'houhanshu', 'a03-111', '《二十四史-後漢書-志第二十一‧郡國三》', '左傳定十年齊歸龜陰之田，杜預曰田在山北。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0263-a03-111-260', 'p0263', 'houhanshu', 'a03-111', '《二十四史-後漢書-志第二十一‧郡國三》', '左傳成二年齊圍龍，杜預曰在縣西南。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0263-a03-111-261', 'p0263', 'houhanshu', 'a03-111', '《二十四史-後漢書-志第二十一‧郡國三》', '又楚有蜀之役，杜預曰縣西北有蜀亭。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0263-a03-111-262', 'p0263', 'houhanshu', 'a03-111', '《二十四史-後漢書-志第二十一‧郡國三》', '左傳隱公「使營菟裘，吾將老焉」，杜預曰縣南有菟裘城。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0263-a03-111-263', 'p0263', 'houhanshu', 'a03-111', '《二十四史-後漢書-志第二十一‧郡國三》', '桓六年會于成，杜預曰縣東南。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0263-a03-111-264', 'p0263', 'houhanshu', 'a03-111', '《二十四史-後漢書-志第二十一‧郡國三》', '左傳會于防，杜預曰在縣東南，有防城。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0263-a03-111-265', 'p0263', 'houhanshu', 'a03-111', '《二十四史-後漢書-志第二十一‧郡國三》', '襄十九年城武城，杜預曰南城縣。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0263-a03-111-266', 'p0263', 'houhanshu', 'a03-111', '《二十四史-後漢書-志第二十一‧郡國三》', '哀十四年司馬牛葬丘輿，杜預曰縣西北有輿城。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0263-a03-111-267', 'p0263', 'houhanshu', 'a03-111', '《二十四史-後漢書-志第二十一‧郡國三》', '左傳隱八年鄭歸祊，杜預曰在縣東南。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0263-a03-111-268', 'p0263', 'houhanshu', 'a03-111', '《二十四史-後漢書-志第二十一‧郡國三》', '閔二年莒人歸共仲及密，杜預曰縣有密如亭。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0263-a03-111-269', 'p0263', 'houhanshu', 'a03-111', '《二十四史-後漢書-志第二十一‧郡國三》', '左傳襄十二年莒圍台，杜預曰縣南有台亭。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0263-a03-111-270', 'p0263', 'houhanshu', 'a03-111', '《二十四史-後漢書-志第二十一‧郡國三》', '盧左傳隱三年齊鄭尋盧之盟，杜預曰今縣故城。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0263-a03-111-271', 'p0263', 'houhanshu', 'a03-111', '《二十四史-後漢書-志第二十一‧郡國三》', '成二年封銳司徒女石窌，杜預曰縣東有地名石窌。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0263-a03-111-272', 'p0263', 'houhanshu', 'a03-111', '《二十四史-後漢書-志第二十一‧郡國三》', '左傳襄十八年齊禦晉平陰，塹防門，杜預曰在縣北。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0263-a03-111-273', 'p0263', 'houhanshu', 'a03-111', '《二十四史-後漢書-志第二十一‧郡國三》', '又齊登巫山以望晉師，杜預曰在縣東北。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0263-a03-111-274', 'p0263', 'houhanshu', 'a03-111', '《二十四史-後漢書-志第二十一‧郡國三》', '杜預曰汶水北地有棘鄉。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0263-a03-111-275', 'p0263', 'houhanshu', 'a03-111', '《二十四史-後漢書-志第二十一‧郡國三》', '左傳「衞師入郕」，杜預曰東平剛父縣西南有郕鄉。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0263-a03-111-276', 'p0263', 'houhanshu', 'a03-111', '《二十四史-後漢書-志第二十一‧郡國三》', '左傳哀八年齊取闡，杜預曰在縣北，有闡鄉。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0263-a03-111-277', 'p0263', 'houhanshu', 'a03-111', '《二十四史-後漢書-志第二十一‧郡國三》', '左傳莊三十二年遇于梁丘，杜預曰梁丘鄉在縣西南。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0263-a03-111-278', 'p0263', 'houhanshu', 'a03-111', '《二十四史-後漢書-志第二十一‧郡國三》', '杜預曰甲父，古國名，在縣東南。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0263-a03-111-279', 'p0263', 'houhanshu', 'a03-111', '《二十四史-後漢書-志第二十一‧郡國三》', '左傳隱十年「取防」，杜預曰縣西有防城。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0263-a03-111-280', 'p0263', 'houhanshu', 'a03-111', '《二十四史-後漢書-志第二十一‧郡國三》', '鉅野左傳桓七年「焚咸丘」，杜預曰縣西有咸亭。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0263-a03-111-281', 'p0263', 'houhanshu', 'a03-111', '《二十四史-後漢書-志第二十一‧郡國三》', '左傳隱元年費伯城郎，杜預曰縣東南有郁郎亭。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0263-a03-111-282', 'p0263', 'houhanshu', 'a03-111', '《二十四史-後漢書-志第二十一‧郡國三》', '杜預曰茅鄉在昌邑西南。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0263-a03-111-283', 'p0263', 'houhanshu', 'a03-111', '《二十四史-後漢書-志第二十一‧郡國三》', '左傳襄二十一年「邾庶其以漆、閭丘來奔」，杜預曰縣東北有漆鄉，西北有顯閭亭。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0263-a03-111-284', 'p0263', 'houhanshu', 'a03-111', '《二十四史-後漢書-志第二十一‧郡國三》', '哀七年囚邾子負瑕，杜預曰縣西北有瑕丘城。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0263-a03-111-285', 'p0263', 'houhanshu', 'a03-111', '《二十四史-後漢書-志第二十一‧郡國三》', '方與，有武唐亭，左傳桓二年盟于唐，杜預曰在西南。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0263-a03-111-286', 'p0263', 'houhanshu', 'a03-111', '《二十四史-後漢書-志第二十一‧郡國三》', '左傳僖七年盟甯母，杜預曰在縣東。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0263-a03-111-287', 'p0263', 'houhanshu', 'a03-111', '《二十四史-後漢書-志第二十一‧郡國三》', '三十一年臧文仲宿重館，杜預曰縣西北有重鄉城。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0263-a03-111-288', 'p0263', 'houhanshu', 'a03-111', '《二十四史-後漢書-志第二十一‧郡國三》', '左傳襄二十六年「齊烏餘以廩丘奔晉」，杜預曰今縣故城是。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0263-a03-111-289', 'p0263', 'houhanshu', 'a03-111', '《二十四史-後漢書-志第二十一‧郡國三》', '又「襲衞羊角取之」，杜預曰今縣所治城。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0263-a03-111-290', 'p0263', 'houhanshu', 'a03-111', '《二十四史-後漢書-志第二十一‧郡國三》', '又襲我高魚，杜預曰在縣東北。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0263-a03-111-291', 'p0263', 'houhanshu', 'a03-111', '《二十四史-後漢書-志第二十一‧郡國三》', '左傳隱七年「戎執凡伯於楚丘」，杜預曰在縣西南。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0263-a03-111-292', 'p0263', 'houhanshu', 'a03-111', '《二十四史-後漢書-志第二十一‧郡國三》', '左傳隱十年「取郜」，杜預曰縣東南有郜城。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0263-a03-111-293', 'p0263', 'houhanshu', 'a03-111', '《二十四史-後漢書-志第二十一‧郡國三》', '左傳昭三十一年邾黑肱以濫來奔，杜預曰縣所治，城東北有郳城。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0263-a03-111-294', 'p0263', 'houhanshu', 'a03-111', '《二十四史-後漢書-志第二十一‧郡國三》', '厚丘左傳成九年「城中城」，杜預曰在縣西南，有中鄉城。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0263-a03-111-295', 'p0263', 'houhanshu', 'a03-111', '《二十四史-後漢書-志第二十一‧郡國三》', '左傳「齊伐莒，莒子奔紀鄣」，杜預曰縣東北有紀城。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0263-a03-111-296', 'p0263', 'houhanshu', 'a03-111', '《二十四史-後漢書-志第二十一‧郡國三》', '左傳哀三年城啟陽，杜預曰開陽。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0263-a03-111-297', 'p0263', 'houhanshu', 'a03-111', '《二十四史-後漢書-志第二十一‧郡國三》', '左傳隱八年盟浮來，杜預曰邳來山之閒，號曰邳來。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0263-a03-111-298', 'p0263', 'houhanshu', 'a03-111', '《二十四史-後漢書-志第二十一‧郡國三》', '杜預曰：「東莞蒙陰縣西北有夷吾亭，或曰鮑叔解夷吾縛於此，因以為名。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0263-a03-111-299', 'p0263', 'houhanshu', 'a03-111', '《二十四史-後漢書-志第二十一‧郡國三》', '」　諸左傳莊二十九年「城諸」，杜預曰諸縣在城陽郡。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0263-a03-111-300', 'p0263', 'houhanshu', 'a03-111', '《二十四史-後漢書-志第二十一‧郡國三》', '又隱四年「莒人伐杞，取牟婁」，杜預曰縣東北有婁鄉。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0263-a03-111-301', 'p0263', 'houhanshu', 'a03-111', '《二十四史-後漢書-志第二十一‧郡國三》', '左傳成八年申公巫臣會渠丘公，杜預曰縣有蘧丘里。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0263-a03-111-302', 'p0263', 'houhanshu', 'a03-111', '《二十四史-後漢書-志第二十一‧郡國三》', '左傳宣元年會于平州，杜預曰在縣西。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0263-a03-111-303', 'p0263', 'houhanshu', 'a03-111', '《二十四史-後漢書-志第二十一‧郡國三》', '左傳隱六年盟于艾，杜預曰縣東南有艾山。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0263-a03-111-304', 'p0263', 'houhanshu', 'a03-111', '《二十四史-後漢書-志第二十一‧郡國三》', '七年「城中丘」，杜預曰縣東北有中丘亭。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0263-a03-111-305', 'p0263', 'houhanshu', 'a03-111', '《二十四史-後漢書-志第二十一‧郡國三》', '左傳莊九年盟于蔇，杜預曰在縣北。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0263-a03-111-306', 'p0263', 'houhanshu', 'a03-111', '《二十四史-後漢書-志第二十一‧郡國三》', '姑幕左傳昭五年「莒牟夷以牟婁及防茲來奔」，杜預曰縣東北有茲亭。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0263-a03-111-307', 'p0263', 'houhanshu', 'a03-111', '《二十四史-後漢書-志第二十一‧郡國三》', '左傳襄十年滅偪陽，杜預曰即此縣也。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0263-a03-111-308', 'p0263', 'houhanshu', 'a03-111', '《二十四史-後漢書-志第二十一‧郡國三》', '左傳昭十六年齊師至蒲隧，杜預曰縣東有蒲姑陂。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0263-a03-112-309', 'p0263', 'houhanshu', 'a03-112', '《二十四史-後漢書-志第二十二‧郡國四》', '著　於陵杜預曰縣西北有于亭。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0263-a03-112-310', 'p0263', 'houhanshu', 'a03-112', '《二十四史-後漢書-志第二十二‧郡國四》', '土鼓　梁鄒　鄒平　東朝陽杜預曰縣西有崔城。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0263-a03-112-311', 'p0263', 'houhanshu', 'a03-112', '《二十四史-後漢書-志第二十二‧郡國四》', '左傳哀十年「取犁及轅」，杜預曰縣西有轅城。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0263-a03-112-312', 'p0263', 'houhanshu', 'a03-112', '《二十四史-後漢書-志第二十二‧郡國四》', '左傳昭二十五年「齊侯唁公于野井」，杜預曰在縣東。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0263-a03-112-313', 'p0263', 'houhanshu', 'a03-112', '《二十四史-後漢書-志第二十二‧郡國四》', '古薄姑氏，杜預曰薄姑地。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0263-a03-112-314', 'p0263', 'houhanshu', 'a03-112', '《二十四史-後漢書-志第二十二‧郡國四》', '左傳齊侯田于貝丘，杜預曰縣南有地名貝丘。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0263-a03-112-315', 'p0263', 'houhanshu', 'a03-112', '《二十四史-後漢書-志第二十二‧郡國四》', '左傳莊九年「戰于乾時」，杜預曰時水在縣界，岐流，旱則竭涸，故曰乾時。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0263-a03-112-316', 'p0263', 'houhanshu', 'a03-112', '《二十四史-後漢書-志第二十二‧郡國四》', '左傳昭五年「莒牟夷以牟婁及防、茲來奔」，杜預曰縣西南有防亭。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0263-a03-112-317', 'p0263', 'houhanshu', 'a03-112', '《二十四史-後漢書-志第二十二‧郡國四》', '左傳莊元年齊遷紀郚，杜預曰朱虛縣東南有郚城。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0263-a03-112-318', 'p0263', 'houhanshu', 'a03-112', '《二十四史-後漢書-志第二十二‧郡國四》', '左傳襄六年圍棠，杜預曰棠國也。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0263-a03-112-319', 'p0263', 'houhanshu', 'a03-112', '《二十四史-後漢書-志第二十二‧郡國四》', '左傳襄二十四年「伐莒，侵介根」，杜預曰縣東北計基城。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0263-a03-112-320', 'p0263', 'houhanshu', 'a03-112', '《二十四史-後漢書-志第二十二‧郡國四》', '左傳齊戍葵丘，杜預曰在縣西。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0263-a03-112-321', 'p0263', 'houhanshu', 'a03-112', '《二十四史-後漢書-志第二十二‧郡國四》', '左傳莊元年齊所徙，杜預曰在縣東南。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0263-a03-112-322', 'p0263', 'houhanshu', 'a03-112', '《二十四史-後漢書-志第二十二‧郡國四》', '左傳鬬緡以權叛，楚遷於那處，杜預曰：縣東南有那口城。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0263-a03-112-323', 'p0263', 'houhanshu', 'a03-112', '《二十四史-後漢書-志第二十二‧郡國四》', '當陽杜預曰縣東南有權城。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0263-a03-112-324', 'p0263', 'houhanshu', 'a03-112', '《二十四史-後漢書-志第二十二‧郡國四》', '杜預曰縣西舊羅國，後徙枝江。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0263-a03-112-325', 'p0263', 'houhanshu', 'a03-112', '《二十四史-後漢書-志第二十二‧郡國四》', '左傳楚文王伐黃，還及湫，杜預曰縣東南有湫城。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0263-a03-112-326', 'p0263', 'houhanshu', 'a03-112', '《二十四史-後漢書-志第二十二‧郡國四》', '杜預曰：「古䢵國，在東南，有䢵城。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0263-a03-112-327', 'p0263', 'houhanshu', 'a03-112', '《二十四史-後漢書-志第二十二‧郡國四》', '左傳楚公子比為王次魚陂，杜預曰在縣西北。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0263-a03-112-328', 'p0263', 'houhanshu', 'a03-112', '《二十四史-後漢書-志第二十二‧郡國四》', '雲杜杜預曰縣東南有鄖城，故國。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0263-a03-112-329', 'p0263', 'houhanshu', 'a03-112', '《二十四史-後漢書-志第二十二‧郡國四》', '浚遒左傳哀十二年會吳于橐皐，杜預曰在縣東南。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0263-a03-112-330', 'p0263', 'houhanshu', 'a03-112', '《二十四史-後漢書-志第二十二‧郡國四》', '左傳成七年吳入州來，杜預曰下蔡縣。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0263-a03-112-331', 'p0263', 'houhanshu', 'a03-112', '《二十四史-後漢書-志第二十二‧郡國四》', '左傳襄三年楚子伐吳，剋鳩茲，杜預曰在縣之東。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0263-a03-112-332', 'p0263', 'houhanshu', 'a03-112', '《二十四史-後漢書-志第二十二‧郡國四》', '左傳昭五年吳敗楚鵲岸，杜預曰縣有鵲尾渚。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0263-a03-112-333', 'p0263', 'houhanshu', 'a03-112', '《二十四史-後漢書-志第二十二‧郡國四》', '左傳昭二十三年吳敗諸侯之師于雞父，杜預曰縣南有雞備亭。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0263-a03-112-334', 'p0263', 'houhanshu', 'a03-112', '《二十四史-後漢書-志第二十二‧郡國四》', '又吳伐越，敗之夫椒，杜預曰太湖中椒山是也。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0263-a03-112-335', 'p0263', 'houhanshu', 'a03-112', '《二十四史-後漢書-志第二十二‧郡國四》', '烏程左傳襄三年楚伐吳至於衡山，杜預曰在縣南。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0263-a03-112-336', 'p0263', 'houhanshu', 'a03-112', '《二十四史-後漢書-志第二十二‧郡國四》', '曲阿　由拳左傳曰越敗吳於檇李，杜預曰縣南醉李城也。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0263-a03-113-337', 'p0263', 'houhanshu', 'a03-113', '《二十四史-後漢書-志第二十三‧郡國五》', '杜預曰：「定安陰密縣，古密須國。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0263-a03-113-338', 'p0263', 'houhanshu', 'a03-113', '《二十四史-後漢書-志第二十三‧郡國五》', '左傳哀四年齊伐晉壺口，杜預曰：「潞縣東有壺口關。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0263-a03-113-339', 'p0263', 'houhanshu', 'a03-113', '《二十四史-後漢書-志第二十三‧郡國五》', '中都左傳昭二年執陳無宇於中都，杜預曰界休縣南中都城是也。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0263-a03-119-340', 'p0263', 'houhanshu', 'a03-119', '《二十四史-後漢書-志第二十九‧輿服上》', '」杜預注左傳亦云「鸞在鑣，和在衡」。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0263-a03-119-341', 'p0263', 'houhanshu', 'a03-119', '《二十四史-後漢書-志第二十九‧輿服上》', '」杜預曰：「纓在馬膺前，如索帬。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0263-a03-120-342', 'p0263', 'houhanshu', 'a03-120', '《二十四史-後漢書-志第三十‧輿服下》', '」杜預注左傳曰：「白與黑謂之黼，黑與青謂之黻。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0263-a03-120-343', 'p0263', 'houhanshu', 'a03-120', '《二十四史-後漢書-志第三十‧輿服下》', '」杜預曰：「鞞，佩刀削上飾。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0263-a04-028-344', 'p0263', 'sanguozhi', 'a04-028', '《三國志·魏書二十八》', '」杜預言於衆曰：「伯玉其不免乎！');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0263-a04-044-345', 'p0263', 'sanguozhi', 'a04-044', '《三國志·蜀書十四》', '會與維出則同轝，坐則同席，謂長史杜預曰：「以伯約比中土名士，公休、太初不能勝也。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0263-a04-048-346', 'p0263', 'sanguozhi', 'a04-048', '《三國志·吳書三》', '冬，晉命鎮東大將軍司馬伷向涂中，安東將軍王渾、揚州刺史周浚向牛渚，建威將軍王戎向武昌，平南將軍胡奮向夏口，鎮南將軍杜預向江陵，龍驤將軍王濬、廣武將軍唐彬浮江東下，太尉賈充為大都督，量宜處要，盡軍勢之中。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0263-a05-003-347', 'p0263', 'jinshu', 'a05-003', '《晉書·卷三》', '辛卯，以尚書杜預都督荊州諸軍事。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0263-a05-003-348', 'p0263', 'jinshu', 'a05-003', '《晉書·卷三》', '十一月，大舉伐吳，遣鎮軍將軍、琅邪王伷出涂中，安東將軍王渾出江西，建威將軍王戎出武昌，平西將軍胡奮出夏口，鎮南大將軍杜預出江陵，龍驤將軍王濬、廣武將軍唐彬率巴蜀之卒浮江而下，東西凡二十餘萬。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0263-a05-003-349', 'p0263', 'jinshu', 'a05-003', '《晉書·卷三》', '甲戌，杜預剋江陵，斬吳江陵督伍延；平南將軍胡奮剋江安。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0263-a05-003-350', 'p0263', 'jinshu', 'a05-003', '《晉書·卷三》', '杜預當鎮靜零、桂，懷輯衡陽。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0263-a05-003-351', 'p0263', 'jinshu', 'a05-003', '《晉書·卷三》', '庚辰，以王濬為輔國大將軍、襄陽侯，杜預當陽侯，王戎安豐侯，唐彬上庸侯，賈充、琅邪王伷以下增封。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0263-a05-003-352', 'p0263', 'jinshu', 'a05-003', '《晉書·卷三》', '閏月，鎮南大將軍、當陽侯杜預卒。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0263-a05-018-353', 'p0263', 'jinshu', 'a05-018', '《晉書·卷十八》', '當陽侯杜預著春秋長歷，說云：');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0263-a05-018-354', 'p0263', 'jinshu', 'a05-018', '《晉書·卷十八》', '杜預又以為周衰世亂，學者莫得其真，今之所傳七歷，皆未必是時王之術也。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0263-a05-034-355', 'p0263', 'jinshu', 'a05-034', '《晉書-卷三十四・列傳第四》', '疾漸篤，乃舉杜預自代。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0263-a05-034-356', 'p0263', 'jinshu', 'a05-034', '《晉書-卷三十四・列傳第四》', '望其碑者莫不流涕，杜預因名爲墮淚碑。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0263-a05-034-357', 'p0263', 'jinshu', 'a05-034', '《晉書-卷三十四・列傳第四》', '杜預字元凱，京兆杜陵人也。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0263-a05-034-358', 'p0263', 'jinshu', 'a05-034', '《晉書-卷三十四・列傳第四》', '每大樹似癭，輒斫使白，題曰「杜預頸」。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0263-a05-034-359', 'p0263', 'jinshu', 'a05-034', '《晉書-卷三十四・列傳第四》', '杜預不有生知，用之則習，振長策而攻取，兼儒風而轉戰。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0263-a05-034-360', 'p0263', 'jinshu', 'a05-034', '《晉書-卷三十四・列傳第四》', '徇以苟合，不求其正，以當代之元良，爲諸侯之庶子，檀弓習於變禮者也，杜預其有焉。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0263-a05-036-full-361', 'p0263', 'jinshu', 'a05-036-full', '《晉書・卷三十六・列傳第六（完整正文）》', '初，杜預聞瓘殺鄧艾，言於眾曰：「伯玉其不免乎！');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0263-a05-036-362', 'p0263', 'jinshu', 'a05-036', '《晉書-卷三十六・列傳第六》', '初，杜預聞瓘殺鄧艾，言於眾曰：「伯玉其不免乎！');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0263-a05-040-363', 'p0263', 'jinshu', 'a05-040', '《晉書-卷四十・列傳第十》', '太傅鄭沖，又與司空荀顗、中書監荀勖、中軍將軍羊祜、中護軍王業，及廷尉杜友、守河南尹杜預、散騎侍郎裴楷、潁川太守周雄、齊相郭頎、騎都尉成公綏荀煇、尚書郎柳軌等，典正其事。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0263-a05-040-364', 'p0263', 'jinshu', 'a05-040', '《晉書-卷四十・列傳第十》', '杜預聞充有奏，馳表固爭，言平在旦夕。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0263-a05-042-365', 'p0263', 'jinshu', 'a05-042', '《晉書-卷四十二・列傳第十二》', '又杜預表請，帝乃發詔，分命諸方節度。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0263-a05-042-366', 'p0263', 'jinshu', 'a05-042', '《晉書-卷四十二・列傳第十二》', '初，詔書使濬下建平，受杜預節度，至秣陵，受王渾節度。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0264-a03-013-0', 'p0264', 'houhanshu', 'a03-013', '《後漢書·卷十三》', '干寶晉記曰：「吳王孫皓將其子瑾等，泥首面縛降王濬。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0264-a04-018-1', 'p0264', 'sanguozhi', 'a04-018', '《三國志·魏書十八》', '王濬在益州，受中制募兵討吳，無虎符，斆收濬從事列上，由此召斆還。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0264-a04-048-2', 'p0264', 'sanguozhi', 'a04-048', '《三國志·吳書三》', '冬，晉命鎮東大將軍司馬伷向涂中，安東將軍王渾、揚州刺史周浚向牛渚，建威將軍王戎向武昌，平南將軍胡奮向夏口，鎮南將軍杜預向江陵，龍驤將軍王濬、廣武將軍唐彬浮江東下，太尉賈充為大都督，量宜處要，盡軍勢之中。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0264-a04-048-3', 'p0264', 'sanguozhi', 'a04-048', '《三國志·吳書三》', '而王濬順流將至，司馬伷、王渾皆臨近境。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0264-a04-048-4', 'p0264', 'sanguozhi', 'a04-048', '《三國志·吳書三》', '壬申，王濬最先到，於是受皓之降，解縛焚櫬，延請相見。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0264-a04-048-5', 'p0264', 'sanguozhi', 'a04-048', '《三國志·吳書三》', '干寶晉紀曰：王濬治船於蜀，吳彥取其流柹以呈孫皓，曰：「晉必有攻吳之計，宜增建平兵。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0264-a04-053-6', 'p0264', 'sanguozhi', 'a04-053', '《三國志·吳書八》', '天紀四年，晉軍征皓，皓奉書於司馬伷、王渾、王濬請降，其文，瑩所造也。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0264-a04-058-7', 'p0264', 'sanguozhi', 'a04-058', '《三國志·吳書十三》', '天紀四年，晉軍伐吳，龍驤將軍王濬順流東下，所至輒克，終如抗慮。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0264-a04-058-8', 'p0264', 'sanguozhi', 'a04-058', '《三國志·吳書十三》', '二月壬戌，晏為王濬別軍所殺。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0264-a05-003-9', 'p0264', 'jinshu', 'a05-003', '《晉書·卷三》', '十一月，大舉伐吳，遣鎮軍將軍、琅邪王伷出涂中，安東將軍王渾出江西，建威將軍王戎出武昌，平西將軍胡奮出夏口，鎮南大將軍杜預出江陵，龍驤將軍王濬、廣武將軍唐彬率巴蜀之卒浮江而下，東西凡二十餘萬。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0264-a05-003-10', 'p0264', 'jinshu', 'a05-003', '《晉書·卷三》', '二月戊午，王濬、唐彬等剋丹陽城。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0264-a05-003-11', 'p0264', 'jinshu', 'a05-003', '《晉書·卷三》', '三月壬寅，王濬以舟師至于建鄴之石頭，孫皓大懼，面縳輿櫬，降于軍門。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0264-a05-003-12', 'p0264', 'jinshu', 'a05-003', '《晉書·卷三》', '庚辰，以王濬為輔國大將軍、襄陽侯，杜預當陽侯，王戎安豐侯，唐彬上庸侯，賈充、琅邪王伷以下增封。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0264-a05-003-13', 'p0264', 'jinshu', 'a05-003', '《晉書·卷三》', '以鎮軍大將軍王濬為撫軍大將軍。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0264-a05-003-14', 'p0264', 'jinshu', 'a05-003', '《晉書·卷三》', '庚子，撫軍大將軍、襄陽侯王濬卒。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0264-a05-003-15', 'p0264', 'jinshu', 'a05-003', '《晉書·卷三》', '馬隆西伐，王濬南征，師不延時，獯虜削迹，兵無血刃，揚越為墟。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0264-a05-006-16', 'p0264', 'jinshu', 'a05-006', '《晉書·卷六》', '及吳之亡，王濬實先至建鄴，而皓之降款，遠歸璽於琅邪。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0264-a05-034-17', 'p0264', 'jinshu', 'a05-034', '《晉書-卷三十四・列傳第四》', '」會益州刺史王濬徵爲大司農，祜知其可任，濬又小字阿童，因表留濬監益州諸軍事，加龍驤將軍，密令修舟楫，爲順流之計。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0264-a05-034-18', 'p0264', 'jinshu', 'a05-034', '《晉書-卷三十四・列傳第四》', '歆遣軍出距王濬，大敗而還。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0264-a05-034-19', 'p0264', 'jinshu', 'a05-034', '《晉書-卷三十四・列傳第四》', '王濬先列上得孫歆頭，預後生送歆，洛中以爲大笑。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0264-a05-039-20', 'p0264', 'jinshu', 'a05-039', '《晉書-卷三十九・列傳第九》', '及王濬表請伐吳，勖與賈充固諫不可，帝不從，而吳果滅。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0264-a05-039-21', 'p0264', 'jinshu', 'a05-039', '《晉書-卷三十九・列傳第九》', '伐吳之役，紞領汝南太守，以郡兵隨王濬入秣陵。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0264-a05-040-22', 'p0264', 'jinshu', 'a05-040', '《晉書-卷四十・列傳第十》', '王濬之克武昌也，充遣使表曰：「吳未可悉定，方夏，江淮下溼，疾疫必起，宜召諸軍，以爲後圖。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0264-a05-042-23', 'p0264', 'jinshu', 'a05-042', '《晉書-卷四十二・列傳第十二》', '既而王濬破石頭，降孫皓，威名益振。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0264-a05-042-24', 'p0264', 'jinshu', 'a05-042', '《晉書-卷四十二・列傳第十二》', '自以先據江上，破皓中軍，案甲不進，致在王濬之後。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0264-a05-042-25', 'p0264', 'jinshu', 'a05-042', '《晉書-卷四十二・列傳第十二》', '以其父之故，每排王濬，時議譏焉。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0264-a05-042-26', 'p0264', 'jinshu', 'a05-042', '《晉書-卷四十二・列傳第十二》', '王濬字士治，弘農湖人也。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0264-a05-042-27', 'p0264', 'jinshu', 'a05-042', '《晉書-卷四十二・列傳第十二》', '案故撫軍王濬歷職內外，任兼文武，料敵制勝，明勇獨斷，義存社稷之利，不顧專輒之罪。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0264-a05-042-28', 'p0264', 'jinshu', 'a05-042', '《晉書-卷四十二・列傳第十二》', '後與王濬共伐吳，彬屯據衝要，爲眾軍前驅。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0265-a03-008-full-0', 'p0265', 'houhanshu', 'a03-008-full', '《後漢書·卷八》', '遣北中郎將盧植討張角，左中郎將皇甫嵩、右中郎將朱儁討潁川黃巾。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0265-a03-008-full-1', 'p0265', 'houhanshu', 'a03-008-full', '《後漢書·卷八》', '五月，皇甫嵩、朱儁復與波才等戰於長社，大破之。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0265-a03-008-full-2', 'p0265', 'houhanshu', 'a03-008-full', '《後漢書·卷八》', '皇甫嵩、朱儁大破汝南黃巾於西華。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0265-a03-008-full-3', 'p0265', 'houhanshu', 'a03-008-full', '《後漢書·卷八》', '八月，皇甫嵩與黃巾戰於倉亭，獲其帥。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0265-a03-008-full-4', 'p0265', 'houhanshu', 'a03-008-full', '《後漢書·卷八》', '乙巳，詔皇甫嵩北討張角。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0265-a03-008-full-5', 'p0265', 'houhanshu', 'a03-008-full', '《後漢書·卷八》', '冬十月，皇甫嵩與黃巾賊戰於廣宗，獲張角弟梁。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0265-a03-008-full-6', 'p0265', 'houhanshu', 'a03-008-full', '《後漢書·卷八》', '以皇甫嵩為左車騎將軍。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0265-a03-008-full-7', 'p0265', 'houhanshu', 'a03-008-full', '《後漢書·卷八》', '十一月，皇甫嵩又破黃巾于下曲陽，斬張角弟寶。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0265-a03-008-full-8', 'p0265', 'houhanshu', 'a03-008-full', '《後漢書·卷八》', '北宮伯玉等寇三輔，遣左車騎將軍皇甫嵩討之，不剋。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0265-a03-008-full-9', 'p0265', 'houhanshu', 'a03-008-full', '《後漢書·卷八》', '十一月，涼州賊王國圍陳倉，右將軍皇甫嵩救之。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0265-a03-008-full-10', 'p0265', 'houhanshu', 'a03-008-full', '《後漢書·卷八》', '六年春二月，左將軍皇甫嵩大破王國於陳倉。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0265-a03-008-11', 'p0265', 'houhanshu', 'a03-008', '《後漢書·卷八》', '遣北中郎將盧植討張角，左中郎將皇甫嵩、右中郎將朱儁討潁川黃巾。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0265-a03-008-12', 'p0265', 'houhanshu', 'a03-008', '《後漢書·卷八》', '五月，皇甫嵩、朱儁復與波才等戰於長社，大破之。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0265-a03-008-13', 'p0265', 'houhanshu', 'a03-008', '《後漢書·卷八》', '皇甫嵩、朱儁大破汝南黃巾於西華。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0265-a03-008-14', 'p0265', 'houhanshu', 'a03-008', '《後漢書·卷八》', '八月，皇甫嵩與黃巾戰於倉亭，獲其帥。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0265-a03-008-15', 'p0265', 'houhanshu', 'a03-008', '《後漢書·卷八》', '乙巳，詔皇甫嵩北討張角。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0265-a03-008-16', 'p0265', 'houhanshu', 'a03-008', '《後漢書·卷八》', '冬十月，皇甫嵩與黃巾賊戰於廣宗，獲張角弟梁。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0265-a03-008-17', 'p0265', 'houhanshu', 'a03-008', '《後漢書·卷八》', '以皇甫嵩為左車騎將軍。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0265-a03-008-18', 'p0265', 'houhanshu', 'a03-008', '《後漢書·卷八》', '十一月，皇甫嵩又破黃巾于下曲陽，斬張角弟寶。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0265-a03-008-19', 'p0265', 'houhanshu', 'a03-008', '《後漢書·卷八》', '北宮伯玉等寇三輔，遣左車騎將軍皇甫嵩討之，不剋。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0265-a03-008-20', 'p0265', 'houhanshu', 'a03-008', '《後漢書·卷八》', '十一月，涼州賊王國圍陳倉，右將軍皇甫嵩救之。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0265-a03-008-21', 'p0265', 'houhanshu', 'a03-008', '《後漢書·卷八》', '六年春二月，左將軍皇甫嵩大破王國於陳倉。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0265-a03-009-22', 'p0265', 'houhanshu', 'a03-009', '《後漢書·卷九》', '丁未，征西將軍皇甫嵩為車騎將軍。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0265-a03-009-23', 'p0265', 'houhanshu', 'a03-009', '《後漢書·卷九》', '車騎將軍皇甫嵩為太尉。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0265-a03-009-24', 'p0265', 'houhanshu', 'a03-009', '《後漢書·卷九》', '冬十二月，太尉皇甫嵩免。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0265-a03-045-25', 'p0265', 'houhanshu', 'a03-045', '《後漢書·卷四十五》', '忠後代皇甫嵩為太尉，錄尚書事，以災異免。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0265-a03-048-26', 'p0265', 'houhanshu', 'a03-048', '《後漢書·卷四十八》', '中平二年，漢陽賊邊章、韓遂與羌胡為寇，東侵三輔，時遣車騎將軍皇甫嵩西討之。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0265-a03-057-27', 'p0265', 'houhanshu', 'a03-057', '《後漢書·卷五十七》', '如是則南道斷絕，車騎之軍孤立，時湟中義從胡北宮伯玉等叛，遣左車騎將軍皇甫嵩討之不剋也。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0265-a03-058-28', 'p0265', 'houhanshu', 'a03-058', '《後漢書·卷五十八》', '後為護軍司馬，與左中郎將皇甫嵩俱討賊張角。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0265-a03-058-29', 'p0265', 'houhanshu', 'a03-058', '《後漢書·卷五十八》', '皇甫嵩傳曰：「連結郡國，自青、徐、幽、兾、荊、楊、兖、豫八州之人，莫不畢應。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0265-a03-058-30', 'p0265', 'houhanshu', 'a03-058', '《後漢書·卷五十八》', '時左將軍皇甫嵩精兵三萬屯扶風，勳密相要結，將以討卓。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0265-a03-064-31', 'p0265', 'houhanshu', 'a03-064', '《後漢書·卷六十四》', '及車騎將車皇甫嵩討平黃巾，盛稱植行師方略，嵩皆資用規謀，濟成其功。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0265-a03-066-32', 'p0265', 'houhanshu', 'a03-066', '《後漢書·卷六十六》', '討擊黃巾別帥，大破之，與左中郎將皇甫嵩、右中郎將朱儁等受降數十萬。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0265-a03-066-33', 'p0265', 'houhanshu', 'a03-066', '《後漢書·卷六十六》', '每三公缺，楊彪、皇甫嵩皆讓位於瑞。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0265-a03-071-34', 'p0265', 'houhanshu', 'a03-071', '《後漢書·卷七十一》', '皇甫嵩字義真，安定朝那人，度遼將軍規之兄子也。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0265-a03-071-35', 'p0265', 'houhanshu', 'a03-071', '《後漢書·卷七十一》', '及黃巾起，公卿多薦儁有才略，拜為右中郎將，持節，與左中郎將皇甫嵩討潁川、汝南、陳國諸賊，悉破平之。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0265-a03-071-36', 'p0265', 'houhanshu', 'a03-071', '《後漢書·卷七十一》', '論曰：皇甫嵩、朱儁並以上將之略，受脤倉卒之時。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0265-a03-071-37', 'p0265', 'houhanshu', 'a03-071', '《後漢書·卷七十一》', '」稱「時人說皇甫嵩之不伐，汝豫之戰，歸功朱儁，張角之捷，本之於盧植，收名斂策，斂策，不論其功。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0265-a03-072-38', 'p0265', 'houhanshu', 'a03-072', '《後漢書·卷七十二》', '詔以卓為中郎將，副左車騎將軍皇甫嵩征之。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0265-a03-072-39', 'p0265', 'houhanshu', 'a03-072', '《後漢書·卷七十二》', '乃拜卓前將軍，與左將軍皇甫嵩擊破之。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0265-a03-072-40', 'p0265', 'houhanshu', 'a03-072', '《後漢書·卷七十二》', '及靈帝寑疾，璽書拜卓為并州牧，令以兵屬皇甫嵩。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0265-a03-072-41', 'p0265', 'houhanshu', 'a03-072', '《後漢書·卷七十二》', '使皇甫嵩攻卓弟旻於郿塢，殺其母妻男女，盡滅其族。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0265-a03-078-42', 'p0265', 'houhanshu', 'a03-078', '《後漢書·卷七十八》', '謂皇甫嵩、蔡雍等並被排也。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0265-a03-102-43', 'p0265', 'houhanshu', 'a03-102', '《二十四史-後漢書-志第十二‧天文下》', '至中平元年，黃巾賊起，上遣中郎將皇甫嵩、朱儁等征之，斬首十餘萬級。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0265-a04-006-44', 'p0265', 'sanguozhi', 'a04-006', '《三國志·魏書六》', '靈帝紀曰：中平五年，徵卓為少府，勑以營吏士屬左將軍皇甫嵩，詣行在所。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0265-a04-006-45', 'p0265', 'sanguozhi', 'a04-006', '《三國志·魏書六》', '」六年，以卓為并州牧，又勑以吏兵屬皇甫嵩。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0265-a04-006-46', 'p0265', 'sanguozhi', 'a04-006', '《三國志·魏書六》', '山陽公載記曰：初卓為前將軍，皇甫嵩為左將軍，俱征韓遂，各不相下。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0265-a04-006-47', 'p0265', 'sanguozhi', 'a04-006', '《三國志·魏書六》', '」　張璠漢紀曰：卓抵其手謂皇甫嵩曰：「義真怖未乎？');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0265-a04-006-48', 'p0265', 'sanguozhi', 'a04-006', '《三國志·魏書六》', '太尉周忠、皇甫嵩，司徒淳于嘉、趙溫，司空楊彪、張喜等為公，皆辭拜讓瑞。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0265-a04-008-49', 'p0265', 'sanguozhi', 'a04-008', '《三國志·魏書八》', '吳書曰：會西羌寇邊，皇甫嵩為征西將軍，表請武將。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0265-a04-010-50', 'p0265', 'sanguozhi', 'a04-010', '《三國志·魏書十》', '九州春秋曰：中平元年，車騎將軍皇甫嵩旣破黃巾，威震天下。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0265-a04-032-51', 'p0265', 'sanguozhi', 'a04-032', '《三國志·蜀書二》', '援亦少有名行，太尉皇甫嵩賢其才而以女妻之，丞相諸葛亮以援為祭酒，遷從事中郎，卒官。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0265-a04-046-52', 'p0265', 'sanguozhi', 'a04-046', '《三國志·吳書一》', '漢遣車騎將軍皇甫嵩、中郎將朱儁將兵討擊之。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0266-a03-008-full-0', 'p0266', 'houhanshu', 'a03-008-full', '《後漢書·卷八》', '遣北中郎將盧植討張角，左中郎將皇甫嵩、右中郎將朱儁討潁川黃巾。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0266-a03-008-full-1', 'p0266', 'houhanshu', 'a03-008-full', '《後漢書·卷八》', '盧植破黃巾，圍張角於廣宗。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0266-a03-008-full-2', 'p0266', 'houhanshu', 'a03-008-full', '《後漢書·卷八》', '」尚書盧植追讓、珪等，斬數人，其餘投河而死。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0266-a03-008-3', 'p0266', 'houhanshu', 'a03-008', '《後漢書·卷八》', '遣北中郎將盧植討張角，左中郎將皇甫嵩、右中郎將朱儁討潁川黃巾。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0266-a03-008-4', 'p0266', 'houhanshu', 'a03-008', '《後漢書·卷八》', '盧植破黃巾，圍張角於廣宗。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0266-a03-008-5', 'p0266', 'houhanshu', 'a03-008', '《後漢書·卷八》', '」尚書盧植追讓、珪等，斬數人，其餘投河而死。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0266-a03-035-6', 'p0266', 'houhanshu', 'a03-035', '《後漢書·卷三十五》', '以山東無足問者，乃西入關，因涿郡盧植，事扶風馬融。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0266-a03-039-7', 'p0266', 'houhanshu', 'a03-039', '《後漢書·卷三十九》', '」盧植曰：「牆，載棺車箱也。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0266-a03-054-8', 'p0266', 'houhanshu', 'a03-054', '《後漢書·卷五十四》', '熹平中，以博習舊聞，公車徵拜議郎，華嶠書曰：「與馬日磾、盧植、蔡邕等著作東觀。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0266-a03-060a-9', 'p0266', 'houhanshu', 'a03-060a', '《後漢書·卷六十上》', '涿郡盧植，北海鄭玄，皆其徒也。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0266-a03-064-10', 'p0266', 'houhanshu', 'a03-064', '《後漢書·卷六十四》', '吳祐　延篤　史弼　盧植　趙歧');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0266-a03-064-11', 'p0266', 'houhanshu', 'a03-064', '《後漢書·卷六十四》', '盧植字子幹，涿郡涿人也。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0266-a03-064-12', 'p0266', 'houhanshu', 'a03-064', '《後漢書·卷六十四》', '告守令曰：「故北中郎將盧植，名著海內，學為儒宗，士之楷模，國之楨幹也。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0266-a03-068-13', 'p0266', 'houhanshu', 'a03-068', '《後漢書·卷六十八》', '」同志者乃共刻石立碑，蔡邕為其文，旣而謂涿郡盧植曰：「吾為碑銘多矣，皆有慙德，唯郭有道無愧色耳。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0266-a03-069-14', 'p0266', 'houhanshu', 'a03-069', '《後漢書·卷六十九》', '尚書盧植執戈於閣道䆫下，仰數段珪。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0266-a03-069-15', 'p0266', 'houhanshu', 'a03-069', '《後漢書·卷六十九》', '公卿並出平樂觀，無得從者，唯尚書盧植夜馳河上，王允遣河南中部掾閔貢隨植後。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0266-a03-070-16', 'p0266', 'houhanshu', 'a03-070', '《後漢書·卷七十》', '與楊彪、盧植、蔡邕等典校中書，歷位九卿，遂登台輔。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0266-a03-071-17', 'p0266', 'houhanshu', 'a03-071', '《後漢書·卷七十一》', '時北中郎將盧植及東中郎將董卓討張角，並無功而還，乃詔嵩進兵討之。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0266-a03-071-18', 'p0266', 'houhanshu', 'a03-071', '《後漢書·卷七十一》', '」稱「時人說皇甫嵩之不伐，汝豫之戰，歸功朱儁，張角之捷，本之於盧植，收名斂策，斂策，不論其功。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0266-a03-072-19', 'p0266', 'houhanshu', 'a03-072', '《後漢書·卷七十二》', '中平元年，拜東中郎將，持節，代盧植擊張角於下曲陽，軍敗抵罪。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0266-a03-072-20', 'p0266', 'houhanshu', 'a03-072', '《後漢書·卷七十二》', '」尚書盧植獨曰：「昔太甲旣立不明，太甲，湯孫，太丁子也。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0266-a03-073-21', 'p0266', 'houhanshu', 'a03-073', '《後漢書·卷七十三》', '」後從涿郡盧植學於緱氏山中，略見書傳。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0266-a03-080b-22', 'p0266', 'houhanshu', 'a03-080b', '《後漢書·卷八十下》', '尚書盧植為之誄讚，以昭其懿德。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0266-a03-094-23', 'p0266', 'houhanshu', 'a03-094', '《二十四史-後漢書-志第四‧禮儀上》', '」盧植注曰：「帝，天也。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0266-a03-094-24', 'p0266', 'houhanshu', 'a03-094', '《二十四史-後漢書-志第四‧禮儀上》', '」盧植注禮記曰：「天子耕藉，一發九推耒。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0266-a03-094-25', 'p0266', 'houhanshu', 'a03-094', '《二十四史-後漢書-志第四‧禮儀上》', '」盧植曰：「藉，耕也。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0266-a03-094-26', 'p0266', 'houhanshu', 'a03-094', '《二十四史-後漢書-志第四‧禮儀上》', '」盧植注云：「玄鳥至時，陰陽中，萬物生，故於是以三牲請子於高禖之神。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0266-a03-094-27', 'p0266', 'houhanshu', 'a03-094', '《二十四史-後漢書-志第四‧禮儀上》', '盧植禮記注曰：「選三公老者為三老，卿大夫中之老者為五更，亦參五之也。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0266-a03-095-28', 'p0266', 'houhanshu', 'a03-095', '《二十四史-後漢書-志第五‧禮儀中》', '盧植注曰：「角力，如漢家乘之，引關蹋踘之屬也。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0266-a03-095-29', 'p0266', 'houhanshu', 'a03-095', '《二十四史-後漢書-志第五‧禮儀中》', '」盧植禮記注云：「所以逐衰而迎新。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0266-a03-097-30', 'p0266', 'houhanshu', 'a03-097', '《二十四史-後漢書-志第七‧祭祀上》', '」盧植注曰：「封泰山，告太平，升中和之氣於天也。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0266-a03-097-31', 'p0266', 'houhanshu', 'a03-097', '《二十四史-後漢書-志第七‧祭祀上》', '」盧植注曰：「配林，小山林麓配泰山者也。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0266-a03-098-32', 'p0266', 'houhanshu', 'a03-098', '《二十四史-後漢書-志第八‧祭祀中》', '」盧植注曰：「天宗，六宗之神。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0266-a03-099-33', 'p0266', 'houhanshu', 'a03-099', '《二十四史-後漢書-志第九‧祭祀下》', '」盧植曰：「諸主祭以土地為本也。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0266-a03-108-34', 'p0266', 'houhanshu', 'a03-108', '《二十四史-後漢書-志第十八‧五行六》', '案：本傳盧植上書，丙子蝕自巳過午，旣蝕之後，雲霧晻曖，陳八事以諫。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0266-a03-114-35', 'p0266', 'houhanshu', 'a03-114', '《二十四史-後漢書-志第二十四‧百官一》', '盧植禮注曰：「如周小宰。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0266-a03-115-36', 'p0266', 'houhanshu', 'a03-115', '《二十四史-後漢書-志第二十五‧百官二》', '盧植禮注曰：「如大樂正。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0266-a03-115-37', 'p0266', 'houhanshu', 'a03-115', '《二十四史-後漢書-志第二十五‧百官二》', '盧植禮注曰：「如小樂正。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0266-a03-115-38', 'p0266', 'houhanshu', 'a03-115', '《二十四史-後漢書-志第二十五‧百官二》', '」盧植禮注曰：「大予令如古大胥。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0266-a03-115-39', 'p0266', 'houhanshu', 'a03-115', '《二十四史-後漢書-志第二十五‧百官二》', '盧植禮注曰：「大樂丞如古小胥。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0266-a03-115-40', 'p0266', 'houhanshu', 'a03-115', '《二十四史-後漢書-志第二十五‧百官二》', '董卓為東中郎將，盧植為北中郎將，獻帝以曹植為南中郎將。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0266-a03-115-41', 'p0266', 'houhanshu', 'a03-115', '《二十四史-後漢書-志第二十五‧百官二》', '」案盧植禮注曰：「大行郎亦如謁者，兼舉形貌。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0266-a03-118-42', 'p0266', 'houhanshu', 'a03-118', '《二十四史-後漢書-志第二十八‧百官五》', '盧植禮注曰：「計斷九月，因秦以十月為正故。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0266-a03-119-43', 'p0266', 'houhanshu', 'a03-119', '《二十四史-後漢書-志第二十九‧輿服上》', '」玄注禮含文嘉曰：「蓋旗有九名：日月為常，交龍為旂，通帛為旃，雜帛為物，熊虎為旗，鳥隼為旟，龜蛇為旐，全羽為旞，析羽為旌」盧植注禮記曰：「有鈴曰旂。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0266-a03-119-44', 'p0266', 'houhanshu', 'a03-119', '《二十四史-後漢書-志第二十九‧輿服上》', '」盧植禮記注曰：「軨，轄頭靼也。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0266-a04-006-45', 'p0266', 'sanguozhi', 'a04-006', '《三國志·魏書六》', '」尚書盧植曰：「案尚書太甲旣立不明，伊尹放之桐宮。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0266-a04-006-46', 'p0266', 'sanguozhi', 'a04-006', '《三國志·魏書六》', '與楊彪、盧植、蔡邕等典校中書，歷位九卿，遂登台輔。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0266-a04-022-47', 'p0266', 'sanguozhi', 'a04-022', '《三國志·魏書二十二》', '太祖北征柳城，過涿郡，令告太守曰：「故北中郎將盧植，名著海內，學為儒宗，士之楷模，乃國之楨幹也。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0266-a04-032-48', 'p0266', 'sanguozhi', 'a04-032', '《三國志·蜀書二》', '」年十五，母使行學，與同宗劉德然、遼西公孫瓚俱事故九江太守同郡盧植。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0267-a03-008-full-0', 'p0267', 'houhanshu', 'a03-008-full', '《後漢書·卷八》', '交阯刺史朱儁討交阯、合浦烏滸蠻，破之。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0267-a03-008-full-1', 'p0267', 'houhanshu', 'a03-008-full', '《後漢書·卷八》', '遣北中郎將盧植討張角，左中郎將皇甫嵩、右中郎將朱儁討潁川黃巾。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0267-a03-008-full-2', 'p0267', 'houhanshu', 'a03-008-full', '《後漢書·卷八》', '五月，皇甫嵩、朱儁復與波才等戰於長社，大破之。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0267-a03-008-full-3', 'p0267', 'houhanshu', 'a03-008-full', '《後漢書·卷八》', '皇甫嵩、朱儁大破汝南黃巾於西華。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0267-a03-008-full-4', 'p0267', 'houhanshu', 'a03-008-full', '《後漢書·卷八》', '詔嵩討東郡，朱儁討南陽。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0267-a03-008-full-5', 'p0267', 'houhanshu', 'a03-008-full', '《後漢書·卷八》', '癸巳，朱儁拔宛城，斬黃巾別帥孫夏。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0267-a03-008-6', 'p0267', 'houhanshu', 'a03-008', '《後漢書·卷八》', '交阯刺史朱儁討交阯、合浦烏滸蠻，破之。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0267-a03-008-7', 'p0267', 'houhanshu', 'a03-008', '《後漢書·卷八》', '遣北中郎將盧植討張角，左中郎將皇甫嵩、右中郎將朱儁討潁川黃巾。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0267-a03-008-8', 'p0267', 'houhanshu', 'a03-008', '《後漢書·卷八》', '五月，皇甫嵩、朱儁復與波才等戰於長社，大破之。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0267-a03-008-9', 'p0267', 'houhanshu', 'a03-008', '《後漢書·卷八》', '皇甫嵩、朱儁大破汝南黃巾於西華。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0267-a03-008-10', 'p0267', 'houhanshu', 'a03-008', '《後漢書·卷八》', '詔嵩討東郡，朱儁討南陽。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0267-a03-008-11', 'p0267', 'houhanshu', 'a03-008', '《後漢書·卷八》', '癸巳，朱儁拔宛城，斬黃巾別帥孫夏。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0267-a03-009-12', 'p0267', 'houhanshu', 'a03-009', '《後漢書·卷九》', '太尉周忠免，太僕朱儁為太尉，錄尚書事。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0267-a03-009-13', 'p0267', 'houhanshu', 'a03-009', '《後漢書·卷九》', '秋七月壬子，太尉朱儁免。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0267-a03-038-14', 'p0267', 'houhanshu', 'a03-038', '《後漢書·卷三十八》', '謝承書曰：「尚進善愛人，坐以待旦，擢門下書佐朱儁，恒嘆述之，以為有不凡之操。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0267-a03-045-15', 'p0267', 'houhanshu', 'a03-045', '《後漢書·卷四十五》', '吳書曰，忠字嘉謀，與朱儁共敗李傕於曹陽也。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0267-a03-048-16', 'p0267', 'houhanshu', 'a03-048', '《後漢書·卷四十八》', '中平元年，與中郎將朱儁擊黃巾賊於宛，破之。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0267-a03-054-17', 'p0267', 'houhanshu', 'a03-054', '《後漢書·卷五十四》', '興平元年，代朱儁為太尉，錄尚書事。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0267-a03-058-18', 'p0267', 'houhanshu', 'a03-058', '《後漢書·卷五十八》', '時河南尹朱儁為卓陳軍事。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0267-a03-066-19', 'p0267', 'houhanshu', 'a03-066', '《後漢書·卷六十六》', '討擊黃巾別帥，大破之，與左中郎將皇甫嵩、右中郎將朱儁等受降數十萬。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0267-a03-071-20', 'p0267', 'houhanshu', 'a03-071', '《後漢書·卷七十一》', '於是發天下精兵，博選將帥，以嵩為左中郎將，持節，與右中郎將朱儁，共發五校、三河騎士及募精勇，合四萬餘人，嵩、儁各統一軍，共討潁川黃巾。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0267-a03-071-21', 'p0267', 'houhanshu', 'a03-071', '《後漢書·卷七十一》', '會帝遣騎都尉曹操將兵適至，嵩、操與朱儁合兵更戰，大破之，斬首數萬級。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0267-a03-071-22', 'p0267', 'houhanshu', 'a03-071', '《後漢書·卷七十一》', '朱儁字公偉，會稽上虞人也。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0267-a03-071-23', 'p0267', 'houhanshu', 'a03-071', '《後漢書·卷七十一》', '論曰：皇甫嵩、朱儁並以上將之略，受脤倉卒之時。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0267-a03-071-24', 'p0267', 'houhanshu', 'a03-071', '《後漢書·卷七十一》', '」稱「時人說皇甫嵩之不伐，汝豫之戰，歸功朱儁，張角之捷，本之於盧植，收名斂策，斂策，不論其功。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0267-a03-072-25', 'p0267', 'houhanshu', 'a03-072', '《後漢書·卷七十二》', '」擊破河南尹朱儁於中牟。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0267-a03-080b-26', 'p0267', 'houhanshu', 'a03-080b', '《後漢書·卷八十下》', '靈帝時，從車騎將軍朱儁征黃巾，為別部司馬。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0267-a03-086-27', 'p0267', 'houhanshu', 'a03-086', '《後漢書·卷八十六》', '四年，刺史朱儁擊破之。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0267-a03-102-28', 'p0267', 'houhanshu', 'a03-102', '《二十四史-後漢書-志第十二‧天文下》', '至中平元年，黃巾賊起，上遣中郎將皇甫嵩、朱儁等征之，斬首十餘萬級。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0267-a03-112-29', 'p0267', 'houhanshu', 'a03-112', '《二十四史-後漢書-志第二十二‧郡國四》', '西鄂有精山，朱儁破孫夏。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0267-a04-001-30', 'p0267', 'sanguozhi', 'a04-001', '《三國志·魏書一》', '河間張超甞薦遺于太尉朱儁，稱遺「有冠世之懿，幹時之量。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0267-a04-046-31', 'p0267', 'sanguozhi', 'a04-046', '《三國志·吳書一》', '漢遣車騎將軍皇甫嵩、中郎將朱儁將兵討擊之。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0267-a04-046-32', 'p0267', 'sanguozhi', 'a04-046', '《三國志·吳書一》', '江表傳曰：堅為朱儁所表，為佐軍，留家著壽春。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0267-a04-053-33', 'p0267', 'sanguozhi', 'a04-053', '《三國志·吳書八》', '還本郡，舉茂才，公府辟，皆不就，吳書曰：大將軍何進、太尉朱儁、司空荀爽三府辟為掾，皆稱疾不就。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0268-a03-009-0', 'p0268', 'houhanshu', 'a03-009', '《後漢書·卷九》', '」壬子，曹操殺太中大夫孔融，夷其族。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0268-a03-035-1', 'p0268', 'houhanshu', 'a03-035', '《後漢書·卷三十五》', '國相孔融深敬於玄，屣履造門。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0268-a03-035-2', 'p0268', 'houhanshu', 'a03-035', '《後漢書·卷三十五》', '玄唯有一子益恩，孔融在北海，舉為孝廉；及融為黃巾所圍，益恩赴難隕身。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0268-a03-054-3', 'p0268', 'houhanshu', 'a03-054', '《後漢書·卷五十四》', '將作大匠孔融聞之，不及朝服，往見操曰：獻帝春秋曰：「融見操曰：『刑之不濫，君之明也。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0268-a03-054-4', 'p0268', 'houhanshu', 'a03-054', '《後漢書·卷五十四》', '」孔融魯國男子，明日便當拂衣而去，不復朝矣。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0268-a03-062-5', 'p0268', 'houhanshu', 'a03-062', '《後漢書·卷六十二》', '獻帝頗好文學，恱與彧及少府孔融侍講禁中，旦夕談論。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0268-a03-062-6', 'p0268', 'houhanshu', 'a03-062', '《後漢書·卷六十二》', '魏志曰「魯國孔融才高倨傲，年在羣、紀之閒，先與紀友，後與羣交，更為紀拜，由是顯名」也。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0268-a03-064-7', 'p0268', 'houhanshu', 'a03-064', '《後漢書·卷六十四》', '光祿勳桓典、少府孔融上書薦之，於是就拜歧為太常。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0268-a03-066-8', 'p0268', 'houhanshu', 'a03-066', '《後漢書·卷六十六》', '辟荀爽、孔融等為從事，上除禁黨。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0268-a03-070-9', 'p0268', 'houhanshu', 'a03-070', '《後漢書·卷七十》', '孔融字文舉，魯國人，孔子二十世孫也。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0268-a03-070-10', 'p0268', 'houhanshu', 'a03-070', '《後漢書·卷七十》', '避事之遼東，北海相孔融聞而竒之，數遣人訊問其母，并致餉遺。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0268-a03-070-11', 'p0268', 'houhanshu', 'a03-070', '《後漢書·卷七十》', '」虞浦江表傳曰：「獻帝甞時見慮及少府孔融。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0268-a03-070-12', 'p0268', 'houhanshu', 'a03-070', '《後漢書·卷七十》', '」枉狀奏融曰：「少府孔融，昔在北海，見王室不靜，而招合徒衆，欲規不軌，云『我大聖之後，而見滅於宋，史記曰，魯大夫孟釐子曰：「孔丘，聖人之後，滅於宋。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0268-a03-070-13', 'p0268', 'houhanshu', 'a03-070', '《後漢書·卷七十》', '少府孔融謂彧曰：「袁紹地廣兵彊，田豐、許攸智計之士為其謀，先賢行狀：「豐字元皓，鉅鹿人。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0268-a03-071-14', 'p0268', 'houhanshu', 'a03-071', '《後漢書·卷七十一》', '彭城相汲廉、北海相孔融、沛相袁忠、太山太守應劭、汝南太守徐璆、前九江太守服虔、博士鄭玄等，敢言之行車騎將軍河南尹莫府：蔡質典職儀曰；「諸州刺史上郡并列卿府，言『敢言之』。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0268-a03-074-15', 'p0268', 'houhanshu', 'a03-074', '《後漢書·卷七十四上》', '獻帝春秋曰：「使將作大匠孔融持節之鄴，拜太尉紹為大將軍，改封鄴侯。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0268-a03-074-16', 'p0268', 'houhanshu', 'a03-074', '《後漢書·卷七十四上》', '二年，使將作大匠孔融持節拜紹大將軍，錫弓矢節鉞，虎賁百人，禮含文嘉曰：「九錫一曰車馬，二曰衣服，三曰樂器，四曰朱戶，五曰納陛，六曰虎賁之士百人，七曰斧鉞，八曰弓矢，九曰秬鬯。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0268-a03-080b-17', 'p0268', 'houhanshu', 'a03-080b', '《後漢書·卷八十下》', '府掾孔融、王朗並修刺候焉。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0268-a03-080b-18', 'p0268', 'houhanshu', 'a03-080b', '《後漢書·卷八十下》', '」唯善魯國孔融及弘農楊脩。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0268-a03-080b-19', 'p0268', 'houhanshu', 'a03-080b', '《後漢書·卷八十下》', '孔融退而數之曰：「正平大雅，固當爾邪？');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0268-a04-001-20', 'p0268', 'sanguozhi', 'a04-001', '《三國志·魏書一》', '魏書曰：袁紹宿與故太尉楊彪、大長秋梁紹、少府孔融有隙，欲使公以他過誅之。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0268-a04-001-21', 'p0268', 'sanguozhi', 'a04-001', '《三國志·魏書一》', '臣松之以為楊彪亦曾為魏武所困，幾至於死，孔融竟不免於誅滅，豈所謂先行其言而後從之哉！');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0268-a04-001-22', 'p0268', 'sanguozhi', 'a04-001', '《三國志·魏書一》', '虞溥江表傳曰：獻帝甞特見慮及少府孔融，問融曰：「鴻豫何所優長？');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0268-a04-004-23', 'p0268', 'sanguozhi', 'a04-004', '《三國志·魏書四》', '玄別傳曰：「玄有子，為孔融吏，舉孝廉。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0268-a04-006-24', 'p0268', 'sanguozhi', 'a04-006', '《三國志·魏書六》', '三公並辟，歷豫州刺史，辟荀爽、孔融為從事，遷河南尹、尚書令。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0268-a04-006-25', 'p0268', 'sanguozhi', 'a04-006', '《三國志·魏書六》', '遂北排田楷，東攻孔融，曜兵海隅，是時百姓無主，欣戴之矣。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0268-a04-010-26', 'p0268', 'sanguozhi', 'a04-010', '《三國志·魏書十》', '唯少府孔融高貴其才，上書薦之曰：「淑質貞亮，英才卓犖。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0268-a04-010-27', 'p0268', 'sanguozhi', 'a04-010', '《三國志·魏書十》', '張衡文士傳曰：孔融數薦衡於太祖，欲與相見，而衡疾惡之，意常憤懣。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0268-a04-010-28', 'p0268', 'sanguozhi', 'a04-010', '《三國志·魏書十》', '孔融與康父端書曰：「前日元將來，淵才亮茂，雅度弘毅，偉世之器也。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0268-a04-010-29', 'p0268', 'sanguozhi', 'a04-010', '《三國志·魏書十》', '孔融謂彧曰：「紹地廣兵彊；田豐、許攸，智計之士也，為之謀；審配、逢紀，盡忠之臣也，任其事；顏良、文醜，勇冠三軍，統其兵：殆難克乎！');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0268-a04-010-30', 'p0268', 'sanguozhi', 'a04-010', '《三國志·魏書十》', '陳羣與孔融論汝、潁人物，羣曰：「荀文若、公達、休若、友若、仲豫，當今並無對。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0268-a04-010-31', 'p0268', 'sanguozhi', 'a04-010', '《三國志·魏書十》', '祈與孔融論肉刑，愔與孔融論聖人優劣，並在融集。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0268-a04-011-32', 'p0268', 'sanguozhi', 'a04-011', '《三國志·魏書十一》', '初平中，北海孔融召以為主簿，守高密令。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0268-a04-011-33', 'p0268', 'sanguozhi', 'a04-011', '《三國志·魏書十一》', '時孔融為北海相，舉原有道。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0268-a04-011-34', 'p0268', 'sanguozhi', 'a04-011', '《三國志·魏書十一》', '時魯國孔融在郡，教選計當任公卿之才，乃以鄭玄為計掾，彭璆為計吏，原為計佐。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0268-a04-011-35', 'p0268', 'sanguozhi', 'a04-011', '《三國志·魏書十一》', '孔融書曰：「隨會在秦，賈季在翟，諮仰靡所，歎息增懷。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0268-a04-012-36', 'p0268', 'sanguozhi', 'a04-012', '《三國志·魏書十二》', '初，太祖性忌，有所不堪者，魯國孔融、融字文舉。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0268-a04-012-37', 'p0268', 'sanguozhi', 'a04-012', '《三國志·魏書十二》', '孔融魯國男子，明日便當褰衣而去，不復朝矣。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0268-a04-012-38', 'p0268', 'sanguozhi', 'a04-012', '《三國志·魏書十二》', '太祖懼遠近之議也，乃令曰：「太中大夫孔融旣伏其罪矣，然世人多採其虛名，少於核實，見融浮豔，好作變異，眩其誑詐，不復察其亂俗也。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0268-a04-013-39', 'p0268', 'sanguozhi', 'a04-013', '《三國志·卷十三‧魏書十三》', '孔融與朗書曰：「世路隔塞，情問斷絕，感懷增思。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0268-a04-021-40', 'p0268', 'sanguozhi', 'a04-021', '《三國志·魏書二十一》', '」典論曰：今之文人，魯國孔融、廣陵陳琳、山陽王粲、北海徐幹、陳留阮瑀、汝南應瑒、東平劉楨，斯七子者，於學無所遺，於辭無所假，咸自以騁騏驥於千里，仰齊足而並馳。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0268-a04-021-41', 'p0268', 'sanguozhi', 'a04-021', '《三國志·魏書二十一》', '孔融體氣高妙，有過人者，然不能持論，理不勝辭，至于雜以嘲戲；及其所善，揚、班之儔也。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0268-a04-021-42', 'p0268', 'sanguozhi', 'a04-021', '《三國志·魏書二十一》', '及孔融有過，太祖使粹為奏，承指數致融罪，其大略言：「融昔在北海，見王室不寧，招合徒衆，欲圖不軌，言『我大聖之後也，而滅於宋。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0268-a04-022-43', 'p0268', 'sanguozhi', 'a04-022', '《三國志·魏書二十二》', '」魯國孔融高才倨傲，年在紀、羣之間，先與紀友，後與羣交，更為紀拜，由是顯名。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0268-a04-026-44', 'p0268', 'sanguozhi', 'a04-026', '《三國志·魏書二十六》', '」故太尉楊彪收付縣獄，尚書令荀彧、少府孔融等並屬寵：「但當受辭，勿加考掠。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0268-a04-032-45', 'p0268', 'sanguozhi', 'a04-032', '《三國志·蜀書二》', '」北海相孔融謂先主曰：「袁公路豈憂國忘家者邪？');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0268-a04-047-46', 'p0268', 'sanguozhi', 'a04-047', '《三國志·吳書二》', '為孔融功曹，融稱曰「廊廟才也」。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0268-a04-049-47', 'p0268', 'sanguozhi', 'a04-049', '《三國志·吳書四》', '北海相孔融聞而奇之，數遣人訊問其母，并致餉遺。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0268-a04-051-48', 'p0268', 'sanguozhi', 'a04-051', '《三國志·吳書六》', '初，憲與少府孔融善，融憂其不免禍，乃與曹公書曰：「歲月不居，時節如流，五十之年，忽焉已至。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0268-a04-053-49', 'p0268', 'sanguozhi', 'a04-053', '《三國志·吳書八》', '孔融遺紘書曰：「聞大軍西征，足下留鎮。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0268-a04-053-50', 'p0268', 'sanguozhi', 'a04-053', '《三國志·吳書八》', '」紘旣好文學，又善楷篆，嘗與孔融書自耆。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0268-a04-057-51', 'p0268', 'sanguozhi', 'a04-057', '《三國志·吳書十二》', '翻與少府孔融書，并示以所著易注。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0268-a04-061-52', 'p0268', 'sanguozhi', 'a04-061', '《三國志·吳書十六》', '中郎將豫章徐宗，有名士也，甞到京師，與孔融交結，然儒生誕節，部曲寬縱，不奉節度，為衆作殿，濬遂斬之。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0268-a04-062-53', 'p0268', 'sanguozhi', 'a04-062', '《三國志·吳書十七》', '本姓氏，初為縣吏，後仕郡，郡相孔融嘲儀，言「氏」字「民」無上，可改為「是」，乃遂改焉。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0268-a05-034-54', 'p0268', 'jinshu', 'a05-034', '《晉書-卷三十四・列傳第四》', '祜前母，孔融女，生兄發，官至都督淮北護軍。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0269-a03-001-0', 'p0269', 'houhanshu', 'a03-001', '《後漢書·卷一上》', '」鄭玄尚書中候注云：「日角謂庭中骨起，狀如日。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0269-a03-001-1', 'p0269', 'houhanshu', 'a03-001', '《後漢書·卷一上》', '長一丈，大十圍，以為壘尉；鄭玄注周禮云：「軍壁曰壘。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0269-a03-001-2', 'p0269', 'houhanshu', 'a03-001', '《後漢書·卷一上》', '」鄭玄注云：「百辟，畿內諸侯也。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0269-a03-002-3', 'p0269', 'houhanshu', 'a03-002', '《後漢書·卷二》', '鄭玄注云：「赤舄，為上冕服之舄也。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0269-a03-002-4', 'p0269', 'houhanshu', 'a03-002', '《後漢書·卷二》', '鄭玄注論語云：「踧踖，敬恭貌。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0269-a03-002-5', 'p0269', 'houhanshu', 'a03-002', '《後漢書·卷二》', '鄭玄注儀禮云：「酳，漱也，所以潔口。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0269-a03-002-6', 'p0269', 'houhanshu', 'a03-002', '《後漢書·卷二》', '夏四月戊子，詔曰：「昔歲五穀登衍，鄭玄注周禮云：「五穀，黍、稷、麥、麻、尗也。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0269-a03-002-7', 'p0269', 'houhanshu', 'a03-002', '《後漢書·卷二》', '帝自御塤篪和之，鄭玄注周禮云：「塤，燒土為之，大如鴈子。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0269-a03-003-8', 'p0269', 'houhanshu', 'a03-003', '《後漢書·卷三》', '鄭玄注云：「幽王在外，三公及諸侯隨而行者，皆無復君臣之禮，不肯晨夜省王。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0269-a03-003-9', 'p0269', 'houhanshu', 'a03-003', '《後漢書·卷三》', '鄭玄注云：「福者，福賢者，謂爵祿之也。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0269-a03-003-10', 'p0269', 'houhanshu', 'a03-003', '《後漢書·卷三》', '鄭玄注云：「敦敦然道旁之葦，牧牛羊者無使踐履折傷之，況於人乎！');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0269-a03-004-11', 'p0269', 'houhanshu', 'a03-004', '《後漢書·卷四》', '」鄭玄注云：「太伯，周太王之長子，欲讓其弟季歷。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0269-a03-004-12', 'p0269', 'houhanshu', 'a03-004', '《後漢書·卷四》', '」鄭玄注云：「靡草，薺、亭歷之屬。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0269-a03-004-13', 'p0269', 'houhanshu', 'a03-004', '《後漢書·卷四》', '」鄭玄注云：「大矣后稷之在其母懷也，終人道十月而生。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0269-a03-005-14', 'p0269', 'houhanshu', 'a03-005', '《後漢書·卷五》', '」鄭玄云：「元，首也。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0269-a03-005-15', 'p0269', 'houhanshu', 'a03-005', '《後漢書·卷五》', '」鄭玄注云：「雩，吁也，嗟而求雨。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0269-a03-005-16', 'p0269', 'houhanshu', 'a03-005', '《後漢書·卷五》', '鄭玄注云：「助老氣也。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0269-a03-005-17', 'p0269', 'houhanshu', 'a03-005', '《後漢書·卷五》', '鄭玄云：「婦使謂組紃之事」其賜人尤貧困、孤弱、單獨穀，人三斛；貞婦有節義十斛，甄表門閭，旌顯厥行。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0269-a03-006-18', 'p0269', 'houhanshu', 'a03-006', '《後漢書·卷六》', '」鄭玄注曰：「為死氣逆生氣也。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0269-a03-007-19', 'p0269', 'houhanshu', 'a03-007', '《後漢書·卷七》', '」鄭玄注云：「造，成也。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0269-a03-007-20', 'p0269', 'houhanshu', 'a03-007', '《後漢書·卷七》', '」鄭玄注云：「允，信也。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0269-a03-007-21', 'p0269', 'houhanshu', 'a03-007', '《後漢書·卷七》', '」鄭玄注云：「雲漢，天河也。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0269-a03-010b-full-22', 'p0269', 'houhanshu', 'a03-010b-full', '《後漢書·卷十下》', '」鄭玄注曰：「納其采擇之禮。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0269-a03-010b-full-23', 'p0269', 'houhanshu', 'a03-010b-full', '《後漢書·卷十下》', '」鄭玄注云：「士大夫已上，乃以玄纁束帛，天子加以穀圭，諸侯加以大璋。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0269-a03-010b-full-24', 'p0269', 'houhanshu', 'a03-010b-full', '《後漢書·卷十下》', '」鄭玄注云：「左道，若巫蠱也。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0269-a03-010b-full-25', 'p0269', 'houhanshu', 'a03-010b-full', '《後漢書·卷十下》', '」鄭玄注曰：「六宮之人，夫人以下，分居后之六宮者。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0269-a03-010b-26', 'p0269', 'houhanshu', 'a03-010b', '《《後漢書》卷十下·皇后紀第十下（獻帝伏皇后節錄）》', '」鄭玄注曰：「六宮之人，夫人以下，分居后之六宮者。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0269-a03-013-27', 'p0269', 'houhanshu', 'a03-013', '《後漢書·卷十三》', '鄭玄注曰：「載，盟辭也。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0269-a03-015-28', 'p0269', 'houhanshu', 'a03-015', '《後漢書·卷十五》', '」鄭玄注云：「痟，酸削也。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0269-a03-015-29', 'p0269', 'houhanshu', 'a03-015', '《後漢書·卷十五》', '」鄭玄注云：「妄之言望，人所望宜正。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0269-a03-016-30', 'p0269', 'houhanshu', 'a03-016', '《後漢書·卷十六》', '諸羌激忿，遂相與解仇結婚，交質盟詛，鄭玄注周禮云：「大事曰盟，小事曰詛。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0269-a03-021-31', 'p0269', 'houhanshu', 'a03-021', '《後漢書·卷二十一》', '」鄭玄注曰：「春秋以禮會民於州序也。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0269-a03-022-32', 'p0269', 'houhanshu', 'a03-022', '《後漢書·卷二十二》', '」鄭玄注云：「黃者，火之子。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0269-a03-023-33', 'p0269', 'houhanshu', 'a03-023', '《後漢書·卷二十三》', '」鄭玄注云：「光明也。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0269-a03-024-34', 'p0269', 'houhanshu', 'a03-024', '《後漢書·卷二十四》', '」鄭玄云：「俑，偶人也。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0269-a03-024-35', 'p0269', 'houhanshu', 'a03-024', '《後漢書·卷二十四》', '」鄭玄曰：「敬父同志如事父也。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0269-a03-024-36', 'p0269', 'houhanshu', 'a03-024', '《後漢書·卷二十四》', '巽下震上，鄭玄注云：「巽為進退，不恒其德之象。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0269-a03-025-37', 'p0269', 'houhanshu', 'a03-025', '《後漢書·卷二十五》', '」鄭玄注禮記云：「申之氣乘之也。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0269-a03-027-38', 'p0269', 'houhanshu', 'a03-027', '《後漢書·卷二十七》', '」鄭玄曰：「在旁曰帷。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0269-a03-027-39', 'p0269', 'houhanshu', 'a03-027', '《後漢書·卷二十七》', '」鄭玄云：「所以廣敬。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0269-a03-027-40', 'p0269', 'houhanshu', 'a03-027', '《後漢書·卷二十七》', '鄭玄云「恂恂，恭順貌」也。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0269-a03-027-41', 'p0269', 'houhanshu', 'a03-027', '《後漢書·卷二十七》', '故月令「仲秋之月養衰老，授几杖，行糜粥飲食」，鄭玄注云「助老氣也」。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0269-a03-029-42', 'p0269', 'houhanshu', 'a03-029', '《後漢書·卷二十九》', '」鄭玄注云：「陳詩謂采其詩而示之。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0269-a03-029-43', 'p0269', 'houhanshu', 'a03-029', '《後漢書·卷二十九》', '誠不欲聖朝行誹謗之誅，以傷晏晏之化，鄭玄注尚書考靈耀云：「道德純備謂之塞，寬容覆載謂之晏。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0269-a03-031-44', 'p0269', 'houhanshu', 'a03-031', '《後漢書·卷三十一》', '」鄭玄注禮記曰：「瞀，目不明之貌。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0269-a03-033-45', 'p0269', 'houhanshu', 'a03-033', '《後漢書·卷三十三》', '張豐狂悖，姦黨日增，連年拒守，吏士疲勞，甲冑生蟣蝨，弓弩不得㢮，鄭玄注周禮曰：「㢮，釋下也。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0269-a03-034-46', 'p0269', 'houhanshu', 'a03-034', '《後漢書·卷三十四》', '」鄭玄注云：「畜，起也。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0269-a03-034-47', 'p0269', 'houhanshu', 'a03-034', '《後漢書·卷三十四》', '兾亦改易輿服之制，作平上軿車，鄭玄注周禮云：「軿猶屏也，所用自蔽隱也。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0269-a03-035-48', 'p0269', 'houhanshu', 'a03-035', '《後漢書·卷三十五》', '」鄭玄注曰：「謂巡守至於方嶽，燔柴祭天，告以諸侯之成功也。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0269-a03-035-49', 'p0269', 'houhanshu', 'a03-035', '《後漢書·卷三十五》', '鄭玄注云：「言武王受此萬年之壽，輔佐之臣亦宜蒙餘福也。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0269-a03-035-50', 'p0269', 'houhanshu', 'a03-035', '《後漢書·卷三十五》', '鄭玄字康成，北海高密人也。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0269-a03-035-51', 'p0269', 'houhanshu', 'a03-035', '《後漢書·卷三十五》', '鄭玄別傳曰「玄年十一二，隨母還家，正臘會同列十數人，皆美服盛飾，語言閑通，玄獨漠然如不及，母私督數之，乃曰『此非我志，不在所願』」也。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0269-a03-035-52', 'p0269', 'houhanshu', 'a03-035', '《後漢書·卷三十五》', '鄭玄括囊大典，網羅衆家，括，結也。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0269-a03-037-53', 'p0269', 'houhanshu', 'a03-037', '《後漢書·卷三十七》', '鄭玄注云：「太伯，周太王之長子，次子仲雍，次子季歷。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0269-a03-038-54', 'p0269', 'houhanshu', 'a03-038', '《後漢書·卷三十八》', '鄭玄注禮記云：「圓曰簞，方曰笥。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0269-a03-038-55', 'p0269', 'houhanshu', 'a03-038', '《後漢書·卷三十八》', '鄭玄注禮記云：「天子九門：路門也，應門也，雉門也，庫門也，皐門也，國門也，近郊門也，遠郊門也，關門也。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0269-a03-039-56', 'p0269', 'houhanshu', 'a03-039', '《後漢書·卷三十九》', '」鄭玄注云：「辯，別也。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0269-a03-039-57', 'p0269', 'houhanshu', 'a03-039', '《後漢書·卷三十九》', '」鄭玄注云：「詳，審察之也。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0269-a03-039-58', 'p0269', 'houhanshu', 'a03-039', '《後漢書·卷三十九》', '」鄭玄注云：「諸公三重，諸侯再重，大夫一重，士不重。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0269-a03-040-59', 'p0269', 'houhanshu', 'a03-040', '《後漢書·卷四十上》', '」鄭玄注云：「方猶道也。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0269-a03-040-60', 'p0269', 'houhanshu', 'a03-040', '《後漢書·卷四十上》', '」鄭玄注曰：「顯，光也。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0269-a03-040-61', 'p0269', 'houhanshu', 'a03-040', '《後漢書·卷四十上》', '鄭玄注周禮云「天子城十二門，通十二子」也。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0269-a03-040-62', 'p0269', 'houhanshu', 'a03-040', '《後漢書·卷四十上》', '鄭玄注禮記曰：「廛，市物邸舍也。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0269-a03-040-63', 'p0269', 'houhanshu', 'a03-040', '《後漢書·卷四十上》', '」鄭玄注周禮曰：「肆，市中陳物處也。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0269-a03-040-64', 'p0269', 'houhanshu', 'a03-040', '《後漢書·卷四十上》', '」鄭玄注周禮曰：「澤無水曰藪。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0269-a03-040-65', 'p0269', 'houhanshu', 'a03-040', '《後漢書·卷四十上》', '」周禮夏后氏「世室九階」，鄭玄注云「南面三階，三面各二」也。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0269-a03-040-66', 'p0269', 'houhanshu', 'a03-040', '《後漢書·卷四十上》', '」鄭玄注云：「我敎告王，口語諄諄然。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0269-a03-040-67', 'p0269', 'houhanshu', 'a03-040', '《後漢書·卷四十上》', '鄭玄注禮記曰：「狡，疾也。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0269-a03-040-68', 'p0269', 'houhanshu', 'a03-040', '《後漢書·卷四十上》', '罘罔連紘，籠山絡野，鄭玄注禮記曰：「獸罟曰罘。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0269-a03-040-69', 'p0269', 'houhanshu', 'a03-040', '《後漢書·卷四十上》', '」鄭玄注周禮曰：「結繳於矢謂之矰。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0269-a03-040-70', 'p0269', 'houhanshu', 'a03-040', '《後漢書·卷四十上》', '」鄭玄注禮記曰：「土高曰臺，有木曰榭。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0269-a03-040-71', 'p0269', 'houhanshu', 'a03-040', '《後漢書·卷四十上》', '」鄭玄注曰：「鑾在衡，和在軾，皆金鈴也。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0269-a03-040-72', 'p0269', 'houhanshu', 'a03-040', '《後漢書·卷四十上》', '鄭玄注詩云：「鷖，鳧屬也。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0269-a03-041-73', 'p0269', 'houhanshu', 'a03-041', '《後漢書·卷四十一》', '」鄭玄云：「危猶高也。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0269-a03-042-74', 'p0269', 'houhanshu', 'a03-042', '《後漢書·卷四十二》', '鄭玄注周禮曰：「淺絳也。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0269-a03-042-75', 'p0269', 'houhanshu', 'a03-042', '《後漢書·卷四十二》', '」鄭玄注云：「木性或曲或直，人所用為器者也。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0269-a03-042-76', 'p0269', 'houhanshu', 'a03-042', '《後漢書·卷四十二》', '」鄭玄云：「副，婦人首服，三輔謂之假紒。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0269-a03-042-77', 'p0269', 'houhanshu', 'a03-042', '《後漢書·卷四十二》', '」鄭玄注云：「撙，趨也。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0269-a03-043-78', 'p0269', 'houhanshu', 'a03-043', '《後漢書·卷四十三》', '」鄭玄注曰：「大道，謂三皇、五帝時也。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0269-a03-043-79', 'p0269', 'houhanshu', 'a03-043', '《後漢書·卷四十三》', '」當今中官近習，鄭玄注禮記云：「近習，天子所親幸者。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0269-a03-043-80', 'p0269', 'houhanshu', 'a03-043', '《後漢書·卷四十三》', '臣雖斗筲之人，鄭玄注論語：「筲，竹器，容斗二升。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0269-a03-044-81', 'p0269', 'houhanshu', 'a03-044', '《後漢書·卷四十四》', '鄭玄注論語曰：「諒闇謂凶廬也。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0269-a03-044-82', 'p0269', 'houhanshu', 'a03-044', '《後漢書·卷四十四》', '」鄭玄注云：「岐岐然意有所知也。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0269-a03-045-83', 'p0269', 'houhanshu', 'a03-045', '《後漢書·卷四十五》', '及竇氏敗，酺乃上疏曰：「臣實愚惷，鄭玄注周禮云：「惷愚，癡騃也。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0269-a03-046-84', 'p0269', 'houhanshu', 'a03-046', '《後漢書·卷四十六》', '」鄭玄注云：「禮篇多亡，本數未聞，其中事儀有三千也。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0269-a03-047-85', 'p0269', 'houhanshu', 'a03-047', '《後漢書·卷四十七》', '』」鄭玄注曰：「正丘首，正首丘也。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0269-a03-048-86', 'p0269', 'houhanshu', 'a03-048', '《後漢書·卷四十八》', '鄭玄注云：「無所不至謂諂佞邪媚，無所不為也。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0269-a03-048-87', 'p0269', 'houhanshu', 'a03-048', '《後漢書·卷四十八》', '鄭玄注周禮曰：「水涯曰濆。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0269-a03-049-88', 'p0269', 'houhanshu', 'a03-049', '《後漢書·卷四十九》', '鄭玄注云：「極，中也。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0269-a03-049-89', 'p0269', 'houhanshu', 'a03-049', '《後漢書·卷四十九》', '鄭玄注云：「空府臧則傷財，力役繁則害人，二者奢泰之所致。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0269-a03-049-90', 'p0269', 'houhanshu', 'a03-049', '《後漢書·卷四十九》', '」鄭玄注云：「中饋，酒食也。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0269-a03-049-91', 'p0269', 'houhanshu', 'a03-049', '《後漢書·卷四十九》', '」鄭玄注曰：「逢猶大也。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0269-a03-049-92', 'p0269', 'houhanshu', 'a03-049', '《後漢書·卷四十九》', '」鄭玄注禮記曰：「綸，今有秩、嗇夫所佩也。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0269-a03-049-93', 'p0269', 'houhanshu', 'a03-049', '《後漢書·卷四十九》', '」鄭玄注云：「葛屨賤，皮屨貴，魏俗至冬猶葛屨，可用履霜，利其賤也。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0269-a03-051-94', 'p0269', 'houhanshu', 'a03-051', '《後漢書·卷五十一》', '鄭玄注云：「東方曰𩎟，南方曰任，西方曰朱離，北方曰禁。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0269-a03-051-95', 'p0269', 'houhanshu', 'a03-051', '《後漢書·卷五十一》', '」鄭玄注云：「鎬、方皆北方地名。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0269-a03-051-96', 'p0269', 'houhanshu', 'a03-051', '《後漢書·卷五十一》', '」鄭玄注論語云：「匹夫之守志，重於三軍之死將者也。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0269-a03-052-97', 'p0269', 'houhanshu', 'a03-052', '《後漢書·卷五十二》', '」鄭玄云：「艮為手，手上肩也。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0269-a03-052-98', 'p0269', 'houhanshu', 'a03-052', '《後漢書·卷五十二》', '」鄭玄云：「謂飾其容而見於外曰冶。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0269-a03-052-99', 'p0269', 'houhanshu', 'a03-052', '《後漢書·卷五十二》', '鄭玄注易乾鑿度曰：「陽起於子，陰起於午，天數大分。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0269-a03-053-100', 'p0269', 'houhanshu', 'a03-053', '《後漢書·卷五十三》', '今潁川荀爽載病在道，北海鄭玄北面受署。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0269-a03-054-101', 'p0269', 'houhanshu', 'a03-054', '《後漢書·卷五十四》', '鄭玄注曰：「二為陰爻，得正於內；五，陽爻也，得正於外。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0269-a03-054-102', 'p0269', 'houhanshu', 'a03-054', '《後漢書·卷五十四》', '」鄭玄注云：「敎周宣王求賢人之未仕者。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0269-a03-054-103', 'p0269', 'houhanshu', 'a03-054', '《後漢書·卷五十四》', '」鄭玄注云：「小亦於東，大亦於東，言賦斂多也。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0269-a03-054-104', 'p0269', 'houhanshu', 'a03-054', '《後漢書·卷五十四》', '鄭玄注曰：「霓，邪氣也。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0269-a03-054-105', 'p0269', 'houhanshu', 'a03-054', '《後漢書·卷五十四》', '鄭玄注曰：「祥，吉也，言其漸即吉也。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0269-a03-054-106', 'p0269', 'houhanshu', 'a03-054', '《後漢書·卷五十四》', '」鄭玄注禮記曰：「緌，冠飾也。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0269-a03-057-107', 'p0269', 'houhanshu', 'a03-057', '《後漢書·卷五十七》', '」鄭玄注云：「壞滅之國，徵人起屋舍，築牆壁，百堵同時而起，言趨事也。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0269-a03-057-108', 'p0269', 'houhanshu', 'a03-057', '《後漢書·卷五十七》', '鄭玄注云：「傷今不如古也。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0269-a03-057-109', 'p0269', 'houhanshu', 'a03-057', '《後漢書·卷五十七》', '」鄭玄注云：「審諦於物也。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0269-a03-057-110', 'p0269', 'houhanshu', 'a03-057', '《後漢書·卷五十七》', '」鄭玄注：「七人謂三公及前疑、後承、左輔、右弼。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0269-a03-057-111', 'p0269', 'houhanshu', 'a03-057', '《後漢書·卷五十七》', '鄭玄注云：「虺、蛇冗處，陰之祥也，故為生女。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0269-a03-059-112', 'p0269', 'houhanshu', 'a03-059', '《後漢書·卷五十九》', '」鄭玄注云：「兩書一札，同而別之，長曰質，短曰劑。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0269-a03-059-113', 'p0269', 'houhanshu', 'a03-059', '《後漢書·卷五十九》', '鄭玄注云：「人皆涉，我友未至，我獨待而不涉。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0269-a03-059-114', 'p0269', 'houhanshu', 'a03-059', '《後漢書·卷五十九》', '」鄭玄注云：「結繳於矢謂之矰。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0269-a03-059-115', 'p0269', 'houhanshu', 'a03-059', '《後漢書·卷五十九》', '」鄭玄注云：「太一者，北辰神名也。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0269-a03-059-116', 'p0269', 'houhanshu', 'a03-059', '《後漢書·卷五十九》', '」鄭玄注云：「鞶，小囊，盛帨巾也。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0269-a03-059-117', 'p0269', 'houhanshu', 'a03-059', '《後漢書·卷五十九》', '鄭玄注禮記云：「蹶，行處之貌也。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0269-a03-059-118', 'p0269', 'houhanshu', 'a03-059', '《後漢書·卷五十九》', '」鄭玄注云：「舟，載度物者也。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0269-a03-060a-119', 'p0269', 'houhanshu', 'a03-060a', '《後漢書·卷六十上》', '鄭玄注云：「澤無水曰藪。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0269-a03-060a-120', 'p0269', 'houhanshu', 'a03-060a', '《後漢書·卷六十上》', '」鄭玄注曰：「燿，讀曰哨。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0269-a03-060a-121', 'p0269', 'houhanshu', 'a03-060a', '《後漢書·卷六十上》', '鄭玄注周禮曰「捎，除也」。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0269-a03-060a-122', 'p0269', 'houhanshu', 'a03-060a', '《後漢書·卷六十上》', '」鄭玄注云：「靈沼之水，魚盈滿其中也，皆以跳躍。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0269-a03-060a-123', 'p0269', 'houhanshu', 'a03-060a', '《後漢書·卷六十上》', '」鄭玄注云：「房謂足下跗也，有似於堂房矣。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0269-a03-060a-124', 'p0269', 'houhanshu', 'a03-060a', '《後漢書·卷六十上》', '涿郡盧植，北海鄭玄，皆其徒也。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0269-a03-061-125', 'p0269', 'houhanshu', 'a03-061', '《後漢書·卷六十一》', '」鄭玄云：「如今三月上巳，水上之類也。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0269-a03-061-126', 'p0269', 'houhanshu', 'a03-061', '《後漢書·卷六十一》', '鄭玄注云：不為夷、齊之清，不為惠、連之屈，故曰異於是也。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0269-a03-062-127', 'p0269', 'houhanshu', 'a03-062', '《後漢書·卷六十二》', '論曰：荀爽、鄭玄、申屠蟠俱以儒行為處士，累徵並謝病不詣。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0269-a03-062-128', 'p0269', 'houhanshu', 'a03-062', '《後漢書·卷六十二》', '」鄭玄注曰：「懿，美也。');
